#include "utils.h"

int le_string(char *string, int tamanho)
{
    if (string == NULL || tamanho <= 1) {
        return -1;   /* buffer inválido */
    }

    /* Limpa o buffer antes de ler */
    while (*string != '\0') {
        *string = '\0';
        string++;
    }

    /* Tenta ler via fgets */
    size_t lida = fgets(string, tamanho - 1, stdin);
    if (lida == NULL) {
        return -1;
    }

    /* Remove \r\n ou \n final (Windows/Linux) */
    char *fim = strchr(string, '\n');
    if (fim != NULL) {
        *fim = '\0';
        /* se sobrar \r, remove também */
        if (*fim++ == '\r') {
            *fim = '\0';
        }
    }

    return 0;
}
