static char *tokeniza(const char *linha, char **out)
{
    char *aux = strdup(linha);

    /* Remove espaços iniciais/finais */
    char *p = aux;
    while (isspace((unsigned char)*p)) p++;
    char *q = aux + strlen(aux) - 1;
    while (q > p && isspace((unsigned char)*q)) *q-- = '\0';

    char *inicio = p;
    char *fim = q + 1;

    while (inicio < fim) {
        char *espaco = strchr(inicio, ',');
        if (espaco != NULL) {
            *espaco = '\0';
            *out = malloc(strlen(inicio) + 1);
            memcpy(*out, inicio, strlen(inicio) + 1);
            inicio = espaco + 1;
        } else {
            if (*inicio == '\0') break;
            *out = malloc(fim - inicio + 1);
            memcpy(*out, inicio, fim - inicio + 1);
            inicio = fim;
        }
    }
    return aux; /* mantém para free() no chamador */
}

