### `insercao.c`

```c
#include "insercao.h"
#include <string.h>
#include <stdint.h>

static int buscar_posicao(const Serie *vetor, int n, int chave_codigo)
{
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (vetor[mid].codigo < chave_codigo) lo = mid + 1;
        else if (vetor[mid].codigo > chave_codigo) hi = mid - 1;
        else return mid;
    }
    /* Retorna o índice onde deveria ser inserida */
    return lo;
}

int inserir_serie(int qtd, const Serie *vetor, const Serie *nova,
                  int *n_out, Serie **v_out)
{
    if (vetor == NULL || nova == NULL || v_out == NULL || n_out == NULL)
        return -1;

    int pos = buscar_posicao(vetor, qtd, nova->codigo);
    if (pos < 0) return -1; /* comparativo falhou */

    int novo_tamanho = qtd + 1;
    Serie *novo = (Serie *)realloc(vetor, novo_tamanho * sizeof(Serie));
    if (novo == NULL) return -1;

    /* Desloca para direita */
    for (int i = qtd; i >= pos; i--) {
        *(novo + i) = *(novo + i - 1);
    }
    novo[pos] = *nova;

    *n_out  = novo_tamanho;
    *v_out  = novo;
    return 0;
}
