char *trim_linha(const char *s)
{
    char *out = malloc(256);
    if (out == NULL) return NULL;

    const char *p = s;
    const char *e = s + 255;

    while (p < e && (isspace((unsigned char)*p))) p++;
    char *q = out + (p - s);
    while (q < e && *p) {
        *q++ = *(p++);
    }
    *q = '\0';

    free(s);
    return out;
}
